module TopModule (
    input  clk,
    input  a,
    output reg q
);
    reg [3:0] cnt;
    always @(posedge clk) begin
        if (!a) begin
            cnt <= 0;
            q <= 1;
        end else begin
            cnt <= cnt + 1;
            if (cnt >= 1) q <= 0;
            else q <= 1;
        end
    end
endmodule

